export type ReturnLineItem = { /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "accepted_quantity": string; "allowed_resolution_types": Array<"refund" | "exchange" | "replacement" | "no_monetary_action" | (string & {})>; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "approved_quantity": string; /** Approved quantity that can still be assigned to a new resolution. Every non-canceled resolution reserves its line quantity, including proposed, pending, action-required, failed, and fulfilled resolutions. Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "available_resolution_quantity": string; "bundle_components": Array<BundleComponent>; "bundle_id"?: string; "buyer_note"?: string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "canceled_quantity": string; /** RFC3339 timestamp. Format: date-time. */ "created_at": string; "decided_by"?: ReturnActor; /** RFC3339 timestamp. Format: date-time. */ "decision_at"?: string; "decline_reason"?: "not_eligible" | "quantity_unavailable" | "evidence_missing" | "suspected_abuse" | "merchant_discretion" | "other" | (string & {}); "decline_reason_message"?: string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "declined_quantity": string; "description"?: string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "dispositioned_quantity": string; "eligibility": ReturnLineItemEligibility; "fulfillment"?: (({ /** Current hold details. While this field is present, status continues to show the public work status from before the hold. */ "active_hold"?: { /** Time the hold became active. Format: date-time. */ "created_at": string; "display_reason"?: string; "held_by"?: string; "reason": "payment_review" | "inventory_issue" | "address_issue" | "customer_request" | "provider_issue" | "scheduling_issue" | "fraud_review" | "other" | (string & {}); "reason_notes"?: string; }; "charges"?: Array<FulfillmentChargeLink>; /** Completion evidence timestamp. Format: date-time. */ "completed_at"?: string; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id"?: string; "device_id"?: string; "digital_details"?: DigitalFulfillmentDetails; /** First time this fulfillment reached dispatched. Format: date-time. */ "dispatched_at"?: string; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; "fulfillment_id": string; "line_items": Array<FulfillmentLineItem>; "local_delivery_details"?: DeliveryFulfillmentDetails; "location_id"?: string; "metadata"?: Record<string, string>; "order"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id"?: string; "fulfillment_status"?: "not_fulfilled" | "partially_fulfilled" | "fulfilled" | "canceled" | "not_applicable" | "closed" | (string & {}); "order_id": string; "order_number"?: string; "payment_intent_ids"?: Array<string>; "payment_status": "unpaid" | "partially_paid" | "paid" | (string & {}); "pricing_amounts": PricingAmounts; "refund_status": "none" | "partially_refunded" | "refunded" | (string & {}); "settlement_amounts": SettlementAmounts; "status": "open" | "closed" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "order_id": string; /** Terminal outcome details. The mark_no_show action records its reason here and returns status as failed. */ "outcome"?: { "notes"?: string; /** Time the terminal outcome occurred. Format: date-time. */ "occurred_at": string; "outcome_type": "no_show" | (string & {}); "reason": "customer_no_show" | "provider_no_show" | "location_unavailable" | "scheduling_error" | "other" | (string & {}); }; "packages"?: Array<ExpandedPackageSummary>; /** First time this fulfillment reached packed. Format: date-time. */ "packed_at"?: string; /** First time this fulfillment reached picked. Format: date-time. */ "picked_at"?: string; "pickup_details"?: PickupFulfillmentDetails; /** Read-only current quantity accounting behavior for this fulfillment state. */ "quantity_effect"?: "preserve" | "fulfill" | "release" | (string & {}); "recipient"?: FulfillmentRecipient; /** Provider acceptance state, independent from fulfillment work progress. The accept action sets this field to accepted while status remains pending. */ "request_status": "pending" | "accepted" | (string & {}); "service_details"?: ServiceFulfillmentDetails; "shipments"?: Array<ExpandedShipmentSummary>; /** Public work status. Fulfillments with request_status accepted project to status pending. Fulfillments with outcome.outcome_type no_show project to status failed. A fulfillment with active_hold projects to its public work status from before the hold. - `pending`: Work has not started. Start, schedule, accept, hold, cancel, or fail it as supported_actions allows. - `in_progress`: Work has started and is not yet ready or complete. - `ready`: The fulfillment is ready for pickup, handoff, or completion. - `completed`: All fulfillment work completed successfully. - `canceled`: The fulfillment was intentionally canceled and will not continue. - `failed`: The fulfillment could not be completed. Resolve the recorded reason before creating replacement work. - `scheduled`: The fulfillment is scheduled for its recorded service window. - `preparing`: Warehouse or provider preparation is underway. - `picked`: The assigned items have been picked. - `packed`: The assigned items have been packed. - `dispatched`: The fulfillment left its origin for delivery or handoff. */ "status": "pending" | "in_progress" | "ready" | "completed" | "canceled" | "failed" | "scheduled" | "preparing" | "picked" | "packed" | "dispatched" | (string & {}); /** Read-only actions currently supported for this fulfillment. */ "supported_actions": Array<"complete" | "cancel" | "hold" | "start" | "mark_ready" | "fail" | "schedule" | "accept" | "mark_preparing" | "mark_picked" | "mark_packed" | "dispatch" | "mark_no_show" | (string & {})>; /** When the fulfillment entered a terminal state: completed, canceled, or failed. This records the state transition; completed_at records completion evidence supplied for the fulfillment. Format: date-time. */ "terminal_at"?: string; "type": "shipment" | "pickup" | "local_delivery" | "digital" | "service" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; /** Monotonic fulfillment version for expected_version checks. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 1. */ "version": string; }) | (null)); "fulfillment_id": string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "handed_off_quantity": string; "image"?: Image; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "inspected_quantity": string; /** RFC3339 timestamp. Format: date-time. */ "inspection_waived_at"?: string; "inspection_waived_by"?: ReturnActor; "inspection_waiver_reason"?: "policy_override" | "trusted_in_store_handoff" | "merchant_review" | "other" | (string & {}); "inspection_waiver_reason_message"?: string; "is_inspection_required"?: boolean; "is_policy_overridden": boolean; "merchandise_status": "not_required" | "awaiting_handoff" | "in_transit" | "partially_received" | "received" | "inspection_required" | "partially_inspected" | "inspection_review_required" | "disposition_required" | "resolved" | "exception" | (string & {}); "modifiers": Array<OrderLineItemModifier>; "name": string; "order_line_item_id": string; /** RFC3339 timestamp. Format: date-time. */ "overridden_at"?: string; "overridden_by"?: ReturnActor; "override_reason"?: "customer_service_exception" | "policy_correction" | "risk_review" | "merchant_discretion" | "other" | (string & {}); "override_reason_message"?: string; "product_id"?: string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "received_quantity": string; "receiving_location_id"?: string; "refund_timing"?: "after_approval" | "after_handoff" | "after_receipt" | "after_inspection" | "manual" | (string & {}); /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "rejected_quantity": string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "requested_quantity": string; "requested_resolution_type"?: "refund" | "exchange" | "replacement" | "no_monetary_action" | "correction" | (string & {}); /** Use an exact numeric string, not a floating-point number. Format: int64. */ "resolution_count": string; "resolution_mode"?: "automatic" | "manual" | (string & {}); "resolution_status": "not_selected" | "pending" | "partially_fulfilled" | "requires_action" | "fulfilled" | "failed" | (string & {}); /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "resolved_quantity": string; "return_id": string; "return_line_item_id": string; "return_reason"?: (({ "category_handles": Array<string>; /** RFC3339 timestamp. Format: date-time. */ "created_at": string; "description"?: string; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; "handle": string; "is_note_required": boolean; "name": string; "return_reason_id": string; "source": "flint" | "merchant" | (string & {}); "status": "active" | "archived" | (string & {}); "supported_actions": Array<string>; /** RFC3339 timestamp. Format: date-time. */ "updated_at": string; /** Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "version": string; }) | (null)); "return_reason_handle": string; "return_reason_id": string; "return_reason_name": string; /** How much of the approved quantity the buyer must physically send back; fractional quantities are not supported. Set 0 for a returnless refund, where the buyer keeps the merchandise and the Return still settles the money. Use an exact numeric string, not a floating-point number. Format: int64. */ "return_required_quantity": string; "return_value": ReturnLineItemValue; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "review_required_quantity": string; "selected_options": Array<SelectedProductOption>; "selected_resolution_type"?: "refund" | "exchange" | "replacement" | "no_monetary_action" | (string & {}); "sku"?: string; "status": "requested" | "open" | "completed" | "declined" | "canceled" | (string & {}); "supported_actions": Array<string>; /** RFC3339 timestamp. Format: date-time. */ "updated_at": string; "variant_id"?: string; };
